replace_once('src/app.js', "function msg(t){const target=$('home').classList.contains('hidden')?$('notice'):$('status');target.textContent=t;}\n", "function msg(t){const target=$('home').classList.contains('hidden')?$('notice'):$('status');target.textContent=t;}\nfunction ensureAudio(){try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();}catch{}}\nfunction tone(frequency,duration,wave='sine',volume=0.035,slide=0){if(!audioContext)return;const now=audioContext.currentTime,osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=wave;osc.frequency.setValueAtTime(frequency,now);if(slide)osc.frequency.exponentialRampToValueAtTime(Math.max(1,frequency+slide),now+duration);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(0.001,now+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+duration);}\nfunction playTap(){tone(240,0.055,'triangle',0.045,-85);}\nfunction playShuffle(){tone(520,0.07,'sawtooth',0.018,-280);setTimeout(()=>tone(360,0.09,'triangle',0.022,-190),55);}\n")
replace_once('src/app.js', "currentCode=code;const token=type==='JOIN'?localStorage.getItem(`joker-token-${code}`):null;", "currentCode=code;if(reconnectTimer){clearTimeout(reconnectTimer);reconnectTimer=null;}const token=type==='JOIN'?localStorage.getItem(`joker-token-${code}`):null;")
